package com.fixmer.mared.technology.server.setup;
import com.google.gson.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;
/** Fixed local CLI operations. A queued request never means the owner completed it. */
public final class RenewalService85 {
 private final AtomicBoolean busy=new AtomicBoolean();private volatile JsonObject data=new JsonObject();private volatile String result="IDLE",observed="",notice="";
 public boolean busy(){return busy.get();}public JsonObject data(){return data.deepCopy();}public String result(){return result;}public String observed(){return observed;}public String notice(){return notice;}
 public void run(String root,String action,boolean enabled,long ttl,long margin){
  if(!Set.of("status","save","RENEW","REPAIR","ABORT").contains(action)||!busy.compareAndSet(false,true))return;result="WORKING";
  Thread t=new Thread(()->{Path out=null,err=null;Process p=null;try{
   if(root.isBlank()||!System.getProperty("os.name","").toLowerCase(Locale.ROOT).startsWith("windows"))throw new IllegalStateException("RENEWAL85_WINDOWS_ROOT");Path home=DedicatedPanelService75.bundle();var args=new ArrayList<>(List.of("-3",home.resolve("tools/dedicated_server75.py").toString(),home.toString(),action.equals("status")?"renewal-status":action.equals("save")?"renewal-save":"renewal-request",root));if(action.equals("save"))args.addAll(List.of("--enabled",Boolean.toString(enabled),"--ttl",Long.toString(ttl),"--margin",Long.toString(margin)));else if(!action.equals("status"))args.add(action);
   out=Files.createTempFile(home,"renew85-",".json");err=Files.createTempFile(home,"renew85-",".err");try{p=launch("pyw.exe",args,home,out,err);}catch(java.io.IOException missing){p=launch("py.exe",args,home,out,err);}if(!com.fixmer.genesis.technology.server.remote.ServerHelperProcess116.await(p,30,TimeUnit.SECONDS))throw new IllegalStateException("RENEWAL85_TIMEOUT");if(p.exitValue()!=0){String e=Files.size(err)<=4096?Files.readString(err).trim():"";throw new IllegalStateException(e.matches("RENEWAL85_[A-Z_]{1,60}")?e:"RENEWAL85_REJECTED");}if(Files.size(out)>65536)throw new IllegalStateException("RENEWAL85_RESULT_LIMIT");var d=JsonParser.parseString(Files.readString(out)).getAsJsonObject();if(action.equals("status")){data=d;observed=root;}else notice=action.equals("save")?"SAVED":"QUEUED";result="READ";
  }catch(Exception e){String c=e.getMessage();result=c!=null&&c.matches("RENEWAL85_[A-Z_]{1,60}")?c:"RENEWAL85_REJECTED";}finally{if(p!=null&&p.isAlive()){p.destroy();try{if(!p.waitFor(2,TimeUnit.SECONDS))p.destroyForcibly();}catch(InterruptedException e){Thread.currentThread().interrupt();}}for(Path f:new Path[]{out,err})if(f!=null)try{Files.deleteIfExists(f);}catch(Exception ignored){}busy.set(false);}},"genesis-renewal85");t.setDaemon(true);t.start();
 }
 private static Process launch(String exe,List<String> args,Path home,Path out,Path err)throws Exception{return com.fixmer.genesis.technology.server.remote.ServerHelperProcess116.start(exe,args,home,out,err);}
}
